:13px}.support-field.full{grid-column:1/-1}.support-field label{display:block;margin-bottom:5px;font-size:12px;font-weight:800;color:#272b38}.support-field input,.support-field textarea{width:100%;border:1px solid #dfe3ec;border-radius:11px;background:#fff;padding:11px 12px;color:#171a25;font:500 13px "Vazirmatn";outline:0;transition:.2s}.support-field input:focus,.support-field textarea:focus{border-color:#7778ee;box-shadow:0 0 0 3px rgba(100,102,241,.11)}.support-field textarea{min-height:96px;resize:vertical}.support-privacy{display:flex;align-items:flex-start;gap:8px;margin:1px 0 14px;color:#697084;font-size:11px}.support-privacy input{margin-top:5px}.support-submit{width:100%;height:48px;border:0;border-radius:13px;background:linear-gradient(135deg,#6466f1,#836fea);color:#fff;font:800 14px "Vazirmatn";cursor:pointer}.support-submit:disabled{opacity:.65;cursor:wait}.support-message{display:none;margin-bottom:13px;padding:10px 12px;border-radius:10px;font-size:12px}.support-message.error{display:block;background:#fff0ee;color:#a3362c}.support-success{padding:22px 5px;text-align:center}.support-success-icon{width:56px;height:56px;margin:0 auto 12px;display:grid;place-items:center;border-radius:18px;background:#e7fbf4;color:#128661;font-size:25px}.support-success h3{margin:0 0 6px}.support-success p{color:#697084;font-size:13px}.support-code{display:block;margin:15px 0;padding:12px;border:1px dashed #aeb1ed;border-radius:11px;background:#f5f5ff;direction:ltr;font:800 15px monospace;color:#4547bf}.support-new{border:0;background:none;color:#5355da;font:800 12px "Vazirmatn";cursor:pointer}.support-honeypot{position:absolute!important;left:-9999px!important}.support-backdrop{position:fixed;inset:0;z-index:59;background:rgba(9,11,20,.28);opacity:0;visibility:hidden;transition:.2s}.support-backdrop.open{opacity:1;visibility:visible}@media(max-width:520px){.support-launcher{right:14px;bottom:14px}.support-panel{right:14px;bottom:78px;max-height:calc(100vh - 95px)}.support-grid{grid-template-columns:1fr}.support-field.full{grid-column:auto}.support-backdrop.open{backdrop-filter:blur(2px)}}
</style>

<div class="support-backdrop" id="supportBackdrop"></div>
<section class="support-panel" id="supportPanel" role="dialog" aria-modal="true" aria-labelledby="supportTitle" aria-hidden="true">
