            <input type="hidden" name="type" id="supportType" value="sales">
            <input type="hidden" name="source_url" id="supportSourceUrl" value="">
            <div class="support-types" role="group" aria-label="موضوع درخواست">
                <button class="support-type active" type="button" data-support-type="sales">خرید پنل</button>
                <button class="support-type" type="button" data-support-type="demo">درخواست دمو</button>
                <button class="support-type" type="button" data-support-type="support">پشتیبانی فنی</button>
                <button class="support-type" type="button" data-support-type="other">سایر موارد</button>
