            <div class="support-grid">
                <div class="support-field"><label for="supportName">نام و نام خانوادگی</label><input id="supportName" name="name" maxlength="100" autocomplete="name" required></div>
                <div class="support-field"><label for="supportMobile">شماره موبایل</label><input id="supportMobile" name="mobile" maxlength="16" inputmode="tel" autocomplete="tel" placeholder="۰۹۱۲۱۲۳۴۵۶۷" required></div>
                <div class="support-field"><label for="supportOrganization">نام سازمان <small>(اختیاری)</small></label><input id="supportOrganization" name="organization" maxlength="150" autocomplete="organization"></div>
