<button class="support-launcher" id="supportLauncher" type="button" aria-controls="supportPanel" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M4 13v-2a8 8 0 0 1 16 0v2"/><path d="M4 13a2 2 0 0 1 2-2h1v6H6a2 2 0 0 1-2-2v-2Zm16 0a2 2 0 0 0-2-2h-1v6h1a2 2 0 0 0 2-2v-2ZM17 18c-1 2-2.5 2-5 2"/></svg><span>پشتیبانی و فروش</span></button>

<script>
(() => {
    const panel=document.getElementById('supportPanel'), launcher=document.getElementById('supportLauncher'), close=document.getElementById('supportClose'), backdrop=document.getElementById('supportBackdrop'), form=document.getElementById('supportForm'), body=document.getElementById('supportBody'), message=document.getElementById('supportMessage'), submit=document.getElementById('supportSubmit'), type=document.getElementById('supportType');
    const open=(selected)=>{ if(selected) selectType(selected); panel.classList.add('open');backdrop.classList.add('open');panel.setAttribute('aria-hidden','false');launcher.setAttribute('aria-expanded','true');setTimeout(()=>document.getElementById('supportName')?.focus(),150) };
    const hide=()=>{panel.classList.remove('open');backdrop.classList.remove('open');panel.setAttribute('aria-hidden','true');launcher.setAttribute('aria-expanded','false');launcher.focus()};
    const selectType=(value)=>{type.value=value;document.querySelectorAll('.support-type').forEach(b=>b.classList.toggle('active',b.dataset.supportType===value))};
    launcher.addEventListener('click',()=>panel.classList.contains('open')?hide():open()); close.addEventListener('click',hide);backdrop.addEventListener('click',hide);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&panel.classList.contains('open'))hide()});
    document.querySelectorAll('[data-support-type]').forEach(button=>button.addEventListener('click',()=>button.classList.contains('support-type')?selectType(button.dataset.supportType):open(button.dataset.supportType)));
    document.getElementById('supportSourceUrl').value=location.href;
    form.addEventListener('submit',async e=>{e.preventDefault();message.className='support-message';message.textContent='';submit.disabled=true;submit.textContent='در حال ثبت درخواست…';try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});const data=await response.json();if(!response.ok){const errors=data.errors?Object.values(data.errors).flat():[data.message||'ثبت درخواست انجام نشد.'];throw new Error(errors.join(' '))}body.innerHTML=`<div class="support-success"><div class="support-success-icon">✓</div><h3>درخواست شما ثبت شد</h3><p>همکاران ما درخواست را بررسی می‌کنند. کد زیر را برای پیگیری نگه دارید.</p><code class="support-code"></code><button class="support-new" type="button">ثبت درخواست دیگر</button></div>`;body.querySelector('.support-code').textContent=data.tracking_code;body.querySelector('.support-new').addEventListener('click',()=>location.reload())}catch(error){message.textContent=error.message;message.className='support-message error';message.scrollIntoView({behavior:'smooth',block:'nearest'})}finally{submit.disabled=false;submit.textContent='ثبت درخواست و دریافت کد پیگیری'}});
})();
</script>
